// Clamp pagination server-side; refuse unknown params.
const body = ($input.first().json.body) || $input.first().json || {};
const allowed = new Set(['page','limit','offset']);
if (Object.keys(body).some(k => !allowed.has(k))) throw new Error('DASHBOARD_REQUEST_REJECTED');
const page = Number.isInteger(body.page) && body.page >= 1 && body.page <= 10000 ? body.page : 1;
const limit = Number.isInteger(body.limit) && body.limit >= 1 && body.limit <= 50 ? body.limit : 25;
const offset = Number.isInteger(body.offset) && body.offset >= 0 && body.offset <= 500000 ? body.offset : (page - 1) * limit;
return [{ json: { page, limit, offset } }];

// Final response: strict allowlist + pagination echo. No raw payloads, notes, email, phone, website.
const v = $input.first().json;
const p = $('Request validieren').first().json;
const leads = Array.isArray(v.leads) ? v.leads : [];
const safe = leads.slice(0, p.limit).map((l) => ({
  lead_id: String(l.lead_id || ''),
  created_at: typeof l.created_at === 'string' ? l.created_at : (l.created_at ? new Date(l.created_at).toISOString() : null),
  company_name: typeof l.company_name === 'string' ? l.company_name.slice(0, 200) : '',
  contact_name: typeof l.contact_name === 'string' ? l.contact_name.slice(0, 200) : '',
  processing_status: ['pending','processing','completed','failed'].includes(l.processing_status) ? l.processing_status : 'pending',
  score_band: ['HOT','WARM','COLD'].includes(l.score_band) ? l.score_band : null,
  duplicate_status: ['NEW','POSSIBLE_DUPLICATE','EXISTING_CONTACT'].includes(l.duplicate_status) ? l.duplicate_status : 'NEW',
  review_required: Boolean(l.review_required),
}));
return [{ json: { success: true, total: Number(v.total || 0), page: p.page, limit: p.limit, leads: safe } }];
